// Generates src/content/generated.ts from every JSON file in src/content/tests.
import fs from "node:fs";
import path from "node:path";

const dir = path.resolve("src/content/tests");
const files = fs.readdirSync(dir).filter((f) => f.endsWith(".json")).sort();
const lines = [
  "// AUTO-GENERATED by scripts/gen-content.mjs. Do not edit by hand.",
  'import type { TestDef } from "@/lib/types";',
];
const names = [];
files.forEach((f, i) => {
  const json = JSON.parse(fs.readFileSync(path.join(dir, f), "utf8"));
  if (json.draft) return;
  const n = `t${i}`;
  names.push(n);
  lines.push(`import ${n} from "./tests/${f}";`);
});
lines.push(`export const ALL_TESTS = [${names.join(", ")}] as unknown as TestDef[];`);
fs.writeFileSync(path.resolve("src/content/generated.ts"), lines.join("\n") + "\n");
console.log(`content: ${names.length} tests`);
